             "POST /p HTTP/1.1\r\nHost: t\r\nTransfer-Encoding: chunked;q=1, chunked\r\n\r\n"
           ) == :status_malformed,
           "priv/muro/http/request.muro:1893 te-param-twice"
  end

  test "priv/muro/http/request.muro te-gzip-param-final", %{impl: impl} do
    assert impl.statusOf(
             "POST /p HTTP/1.1\r\nHost: t\r\nTransfer-Encoding: gzip;q=1, chunked\r\n\r\n"
           ) == :status_malformed,
           "priv/muro/http/request.muro:1895 te-gzip-param-final"
  end

  test "priv/muro/http/request.muro keep-enclose", %{impl: impl} do
    assert impl.keepOf("GET /health HTTP/1.1\r\nHost: t\r\nConnection: enclose\r\n\r\n") ==
             :keep_yes,
           "priv/muro/http/request.muro:1897 keep-enclose"
  end

  test "priv/muro/http/request.muro keep-close-foo", %{impl: impl} do
    assert impl.keepOf("GET /health HTTP/1.1\r\nHost: t\r\nConnection: close, foo\r\n\r\n") ==
             :keep_no,
           "priv/muro/http/request.muro:1899 keep-close-foo"
  end

  test "priv/muro/http/request.muro keep-alive-10", %{impl: impl} do
    assert impl.keepOf("GET /health HTTP/1.0\r\nConnection: Keep-Alive\r\n\r\n") == :keep_yes,
           "priv/muro/http/request.muro:1901 keep-alive-10"
  end

  test "priv/muro/http/request.muro keep-ws", %{impl: impl} do
    assert impl.keepOf("GET /health HTTP/1.1\r\nHost: t\r\nConnection:  close \r\n\r\n") ==
             :keep_no,
           "priv/muro/http/request.muro:1903 keep-ws"
  end

  test "priv/muro/http/request.muro keep-closeable", %{impl: impl} do
    assert impl.keepOf("GET /health HTTP/1.1\r\nHost: t\r\nConnection: closeable\r\n\r\n") ==
             :keep_yes,
           "priv/muro/http/request.muro:1905 keep-closeable"
  end

  test "priv/muro/http/request.muro keep-close-then-alive", %{impl: impl} do
    assert impl.keepOf(
             "GET /health HTTP/1.1\r\nHost: t\r\nConnection: close\r\nConnection: keep-alive\r\n\r\n"
           ) == :keep_no,
           "priv/muro/http/request.muro:1907 keep-close-then-alive"
  end

  test "priv/muro/http/request.muro keep-alive-then-close", %{impl: impl} do
    assert impl.keepOf(
             "GET /health HTTP/1.1\r\nHost: t\r\nConnection: keep-alive\r\nConnection: close\r\n\r\n"
           ) == :keep_no,
           "priv/muro/http/request.muro:1909 keep-alive-then-close"
  end
end
